            if isinstance(ip, ipaddress.IPv6Address) and ip.ipv4_mapped:
                ip = ip.ipv4_mapped

            if ip.is_private or ip.is_loopback or ip.is_reserved or ip.is_link_local or ip.is_multicast:
                raise ValueError("Access to private or reserved network addresses is not allowed.")
    except socket.gaierror:
        raise ValueError("Could not resolve hostname.")
    except ValueError as e:
        if "not allowed" in str(e):
            raise
        raise ValueError(f"Invalid IP address resolved: {e}")

    # 3. Setup secure SSL context using certifi
    context = ssl.create_default_context(cafile=certifi.where())

    # 4. Fetch the content
    try:
        # Limit read size to 1MB to prevent memory exhaustion (DoS)
        # Set a timeout to prevent hanging connections
        with urllib.request.urlopen(page_url, context=context, timeout=10) as response:
            html_bytes = response.read(1024 * 1024)
            charset = response.headers.get_content_charset() or 'utf-8'
            html_content = html_bytes.decode(charset, errors='ignore')
    except urllib.error.URLError as e:
        raise RuntimeError(f"Failed to fetch URL: {e}")
    except Exception as e:
        raise RuntimeError(f"An error occurred while fetching the URL: {e}")

    # 5. Parse HTML for metadata
    parser = MetadataParser()
    parser.feed(html_content)

    return {
        "title": parser.title,
        "description": parser.description
    }
